package applicablemodifiers

import (
	"strings"
	"testing"
)

func TestRenderGoEmitsCanonicalForm(t *testing.T) {
	keys := []string{"is_electric", "is_indoor", "is_virtual"}
	got, err := RenderGo("gear", "Gear", keys)
	if err != nil {
		t.Fatalf("RenderGo error: %v", err)
	}
	for _, want := range []string{
		"// Code generated by applicablemodifiersgen; DO NOT EDIT.",
		"package gear",
		"var GearApplicableModifierKeys = []string{",
		`"is_electric"`, `"is_indoor"`, `"is_virtual"`,
		"func IsApplicableModifier(key string) bool {",
	} {
		if !strings.Contains(got, want) {
			t.Fatalf("RenderGo output missing %q:\n%s", want, got)
		}
	}
}
